{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C03"],
      "claim": "Erythromycin, a macrolide sharing the macrocyclic lactone and sugar architecture, achieves only 0.1-2.5 µg/mL CSF versus 8-12 µg/mL serum in meningitis, demonstrating poor BBB penetration for this structural class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Madecassoside, a large polyhydroxylated triterpene glycoside, had brain concentrations below the LLOQ after oral dosing in rats, showing that high polarity and size prevent meaningful CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Loganin, a polar glycoside, had the lowest brain levels and difficulty crossing the BBB in rat tissue distribution, supporting poor CNS exposure for highly polar glycosylated molecules.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Tobramycin, a highly polar ionizable aminoglycoside, had very low or unmeasurable CSF concentrations in neonates, supporting poor CNS access for highly polar charged drugs.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Dictyostatin achieved good brain AUC in mice, but it lacks the query's polyhydroxylated, ionizable mycosamine and carboxylate groups and extreme polarity, so its positive brain penetration is not transferable.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C13"],
      "claim": "Clarithromycin showed 25-45% CSF penetration in rabbits with pneumococcal meningitis, but this occurred under BBB disruption and with a more lipophilic macrolide, so it does not establish meaningful CNS access for the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Prediction: fail. The query is amphotericin B, an extremely large, polar, ionizable polyene macrolide. Transferable evidence from macrolides and large polar glycosides/aminoglycosides indicates inadequate CNS exposure; the few positive analogues either lack the query's extreme polarity or were measured under BBB disruption.",
  "evidence_gaps": [
    "No direct brain or CSF measurement for amphotericin B is present in the provided evidence set.",
    "Morgan similarities are low (0.19-0.23), limiting quantitative transferability.",
    "Positive CNS detection for some glycosides/saponins does not establish meaningful exposure.",
    "Meningitis/inflammation data may overestimate penetration relative to normal BBB conditions."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

